use std::fmt::Debug;

use async_trait::async_trait;
use thiserror::Error;

use crate::DeviceInfo;

/// An opaque, versioned invitation generated by a Mist runtime.
#[derive(Clone, Debug, Eq, PartialEq, uniffi::Record)]
pub struct PairingOffer {
    pub encoded: String,
}

/// An authenticated peer installed into the trusted-device store.
#[derive(Clone, Debug, Eq, PartialEq, uniffi::Record)]
pub struct PairedPeer {
    pub endpoint_id: String,
    pub device: DeviceInfo,
}

/// A pairing operation could not be completed.
#[derive(Debug, Error, uniffi::Error)]
pub enum PairingError {
    #[error("invalid Mist pairing offer: {reason}")]
    InvalidOffer { reason: String },
    #[error("the Mist pairing offer was rejected: {reason}")]
    Rejected { reason: String },
    #[error("failed to generate a secure pairing token: {reason}")]
    TokenGeneration { reason: String },
    #[error("create a pairing offer before waiting for its peer")]
    NoPendingOffer,
    #[error("the Mist pairing offer was cancelled")]
    Cancelled,
    #[error("Mist pairing protocol failed: {reason}")]
    Protocol { reason: String },
    #[error("failed to persist paired device: {reason}")]
    Storage { reason: String },
    #[error("failed to connect to the pairing peer: {reason}")]
    Connect { reason: String },
    #[error("failed to accept the pairing peer: {reason}")]
    Accept { reason: String },
    #[error("the Mist runtime closed before the pairing peer connected")]
    RuntimeClosed,
    #[error("failed to run pairing on the Mist native executor: {reason}")]
    Executor { reason: String },
}

/// Creates and accepts authenticated Mist invitations.
#[uniffi::export]
#[async_trait]
pub trait Pairing: Send + Sync + Debug {
    /// Creates a new opaque, single-use invitation.
    ///
    /// # Errors
    ///
    /// Returns an error when secure randomness or local pairing state fails.
    fn initiate(&self) -> Result<PairingOffer, PairingError>;
    fn cancel(&self);
    async fn accept(&self, offer: PairingOffer) -> Result<PairedPeer, PairingError>;
    async fn wait_for_peer(&self) -> Result<PairedPeer, PairingError>;
}
